<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\DiscordChannel; use App\Models\DiscordGuild; use App\Models\VoiceReport; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class VoiceReportController extends Controller { public function store(Request $request): JsonResponse { $data=$request->validate(['guild_discord_id'=>'required|string|max:255','channel_discord_id'=>'required|string|max:255','reported_user_discord_id'=>'required|string|max:255','reporter_user_discord_id'=>'required|string|max:255','reason'=>'required|string|max:255','comment'=>'nullable|string|max:4000','source'=>'nullable|in:manual,blocked_word','detection_confidence'=>'nullable|numeric|min:0|max:1','detection_metadata'=>'array']); $guild=DiscordGuild::query()->where('discord_id',$data['guild_discord_id'])->firstOrFail(); $channel=DiscordChannel::query()->voiceBased()->where('discord_id',$data['channel_discord_id'])->firstOrFail(); $report=VoiceReport::query()->create(['discord_guild_id'=>$guild->id,'discord_channel_id'=>$channel->id,'reported_user_discord_id'=>$data['reported_user_discord_id'],'reporter_user_discord_id'=>$data['reporter_user_discord_id'],'reason'=>$data['reason'],'comment'=>$data['comment']??null,'source'=>$data['source']??'manual','detection_confidence'=>$data['detection_confidence']??null,'detection_metadata'=>$data['detection_metadata']??[],'status'=>'pending','reported_at'=>now()]); return response()->json(['data'=>['id'=>$report->id,'status'=>$report->status]],201); } }
